class Shape {
public:
    virtual double area() const = 0;   // pure virtual
    virtual ~Shape() = default;
};

class Circle : public Shape {
    double r;
public:
    explicit Circle(double r) : r(r) {}
    double area() const override { return 3.14159 * r * r; }
};

Shape s;          // can't create a Shape
Circle c(2.0);    // fine: area is implemented

class Polygon : public Shape {
public:
    int sides() const { return n; }
protected:
    int n = 0;
};                  // no area(): still abstract

Polygon p;          // error: still abstract

Shape* ptr = new Circle(1.0);   // OK
ptr->area();                    // runs Circle::area
delete ptr;

class Logger {
public:
    virtual void log(const std::string& m) = 0;
    virtual ~Logger() = 0;               // pure virtual dtor
};
void Logger::log(const std::string& m) { std::cout << m; }
Logger::~Logger() {}                     // body REQUIRED

class FileLogger : public Logger {
public:
    void log(const std::string& m) override {
        Logger::log(m);                  // reuse the default
    }
};
